{"content": "#!/usr/bin/env python3
"""Smoke-check milestone 3 (deals) against a running dev server."""
import http.cookiejar
import re
import sys
import time
import urllib.parse
import urllib.request

BASE = "http://127.0.0.1:4099"
cj = http.cookiejar.CookieJar()
opener = urllib.request.build_opener(urllib.request.HTTPCookieProcessor(cj))


def get(path, follow=False):
    req = urllib.request.Request(BASE + path, headers={"User-Agent": "smoke"})
    try:
        resp = opener.open(req)
        return resp.status, resp.read().decode("utf-8", "replace")
    except urllib.error.HTTPError as e:
        return e.code, e.read().decode("utf-8", "replace")


def csrf(html):
    m = re.search(r'name="_csrf_token"[^>]*value="([^"]+)"', html)
    if not m:
        m = re.search(r'name="csrf_token"[^>]*value="([^"]+)"', html)
    return m.group(1) if m else None


def post(path, data):
    body = urllib.parse.urlencode(data).encode()
    req = urllib.request.Request(
        BASE + path, data=body, headers={"Content-Type": "application/x-www-form-urlencoded"}
    )
    try:
        resp = opener.open(req)
        return resp.status, resp.url, resp.read().decode("utf-8", "replace")
    except urllib.error.HTTPError as e:
        return e.code, e.url if hasattr(e, "url") else "", e.read().decode("utf-8", "replace")


def check(name, cond, detail=""):
    print(("PASS  " if cond else "FAIL  ") + name + ((" — " + detail) if detail and not cond else ""))
    if not cond:
        sys.exit(1)


# --- readiness ---
for _ in range(120):
    try:
        status, _ = get("/accounts/log-in")
        if status in (200, 302):
            break
    except Exception:
        pass
    time.sleep(1)
else:
    print("server never became ready")
    sys.exit(1)

# --- logged-out visits bounce to log-in ---
status, _ = get("/contacts")
check("logged-out /contacts bounces", status == 302)
status, _ = get("/contacts/anything/deals/new")
check("logged-out deal route bounces", status == 302)

# --- register through the real form (with CSRF) ---
status, html = get("/accounts/register")
check("register page reachable", status == 200)
token = csrf(html)
check("register page carries a csrf token", token is not None)

email = "smoke-%d@example.com" % int(time.time())
status, url, html = post(
    "/accounts/register",
    {
        "_csrf_token": token,
        "account": {
            "email": email,
            "password": "super secret 1234",
            "password_confirmation": "super secret 1234",
        },
    },
)
check("registration signs in and lands on the pipeline", status == 200 and "/" == url or status == 302, f"{status} {url}")

# signed-in: follow up by GETting the shell page
status, html = get("/")
check("signed-in / renders the shell", status == 200 and "Pipeline" in html)
status, html = get("/contacts")
check("signed-in /contacts renders", status == 200 and "No contacts yet" in html)

print("OK: seeded flow, ready for data-level deal checks (run via mix run).")
", "file_path": "/tmp/deals_smoke.py"}

